"""Correct the imported draft against the selected IELLO base-game manual."""
from copy import deepcopy
from backend.app import Game, read_games, write_game

for game in read_games():
    if game['n'].lower() != 'for sale' or 'IELLO' not in game.get('edition',''):
        continue
    game['source_text'] = game['source_text'].split('[หน้า 11]')[0].strip()
    game['source_scope'] = 'IELLO EN V2 base rules, pages 1-10; optional variant excluded'
    game['r'] = [
        ['ประมูลซื้อบ้าน', 'ฉบับอ้างอิง: IELLO EN V2 กติกาหลัก\n- รอบแรกสุ่มผู้เริ่ม จากนั้นเล่นตามเข็มนาฬิกา\n- เปิดบ้านตามจำนวนผู้เล่น ผู้เล่นเลือกเสนอราคาหรือบอกผ่าน\n- ผู้เล่นต้องเสนอเงินมากกว่าราคาประมูลล่าสุด หรือบอกผ่าน\n- เมื่อบอกผ่านให้รับบ้านมูลค่าต่ำสุดที่เหลือ รับธนบัตรที่ลงไว้คืนครึ่งหนึ่งโดยปัดจำนวนธนบัตรลง และออกจากการประมูลรอบนั้น\n- ถ้าไม่มีธนบัตรเหลือต้องบอกผ่าน\n- คนสุดท้ายที่ยังประมูลอยู่จ่ายธนบัตรที่ลงไว้ทั้งหมด รับบ้านใบสุดท้าย และเริ่มรอบถัดไป'],
        ['ขายบ้านและตัดสินผู้ชนะ', '- เปิดเช็คตามจำนวนผู้เล่น\n- ทุกคนเลือกบ้านหนึ่งใบคว่ำไว้แล้วเปิดพร้อมกัน บ้านเลขสูงสุดได้เช็คสูงสุด ที่เหลือเรียงตามลำดับ\n- เก็บเช็คไว้คว่ำหน้า บ้านที่ขายแล้วออกจากการเล่น\n- เมื่อขายบ้านครบให้นับเงินจากเช็คและธนบัตรที่ไม่ได้ใช้ ผู้มีเงินรวมมากที่สุดชนะ\n- ถ้าเงินรวมเท่ากัน ผู้เหลือธนบัตรมากกว่าชนะ ถ้ายังเท่ากันชนะร่วมกัน'],
    ]
    game['st'] = deepcopy(game['r'])
    game['qz'] = [
        {'c':'ราคาประมูลล่าสุด 4,000 คุณเสนอ 3,000 ได้หรือไม่?', 'o':['ไม่ได้ ต้องเสนอมากกว่าราคาล่าสุด','ได้ เพราะเป็นตาของเรา','ได้ ถ้าคนอื่นตกลง'], 'a':0, 'w':'กติกาการเสนอราคากำหนดให้เพิ่มจากราคาล่าสุด ดังนั้น 3,000 ต่ำกว่า 4,000 จึงใช้ไม่ได้'},
        {'c':'คุณลงธนบัตรไป 5 ใบแล้วบอกผ่าน จะได้คืนกี่ใบ?', 'o':['2 ใบ','3 ใบ','5 ใบ'], 'a':0, 'w':'ได้ธนบัตรคืนครึ่งหนึ่งโดยปัดจำนวนธนบัตรลง ครึ่งของ 5 คือ 2.5 จึงคืน 2 ใบ ตามกติกา IELLO EN V2'},
        {'c':'เมื่อคุณเป็นคนสุดท้ายที่ยังประมูลอยู่ ต้องจ่ายเท่าไร?', 'o':['ธนบัตรที่ลงไว้ทั้งหมด','ครึ่งหนึ่งปัดลง','ไม่ต้องจ่าย'], 'a':0, 'w':'คนสุดท้ายจ่ายเงินที่ลงไว้ทั้งหมดแล้วรับบ้านใบสุดท้าย ไม่ใช้กฎคืนครึ่งหนึ่งของผู้บอกผ่าน'},
    ]
    game['sit'] = [
        {'c':'ราคาล่าสุด 4,000 คุณมีเงิน 3,000 และไม่สามารถเพิ่มราคาได้ ทางเลือกใดอยู่ในกติกา?', 'o':['บอกผ่าน','ลดราคาประมูลเป็น 3,000','รับบ้านฟรีทันที'], 'a':0, 'w':'ในตาของคุณเลือกเพิ่มราคาหรือบอกผ่านได้ ถ้าเพิ่มไม่ได้ยังมีทางเลือกบอกผ่าน'},
        {'c':'คุณลงธนบัตร 6 ใบและเป็นคนสุดท้ายที่ไม่บอกผ่าน ต้องทำอย่างไร?', 'o':['จ่ายทั้ง 6 ใบและรับบ้านใบสุดท้าย','จ่าย 3 ใบและเลือกบ้านใดก็ได้','รับเงินคืนทั้งหมด'], 'a':0, 'w':'คนสุดท้ายจ่ายธนบัตรที่ลงไว้ทั้งหมดและได้รับบ้านใบสุดท้าย'},
        {'c':'ช่วงขายบ้าน คุณเปิดบ้านเลขสูงสุดในรอบ จะรับเช็คใด?', 'o':['เช็คมูลค่าสูงสุดที่เปิดอยู่','เช็คมูลค่าต่ำสุด','เลือกเช็คจากกองโดยไม่เปิด'], 'a':0, 'w':'เรียงมูลค่าบ้านกับเช็ค ผู้เปิดบ้านสูงสุดรับเช็คสูงสุด'},
    ]
    write_game(Game(**game))
    print('Reconciled For Sale rules, lessons, scenarios and quiz; image and other metadata preserved.')
